import React from "react";
import { render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./SideNav.stories";
import SideNav from ".";

const { Multilevel } = composeStories(stories) as any;

describe("SideNav component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Multilevel />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props to the nav element", () => {
    render(<SideNav open data-testid="sidenav"></SideNav>);
    expect(screen.queryByRole("navigation")).toHaveAttribute(
      "data-testid",
      "sidenav"
    );
  });
});
